import os,glob,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))

def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    blocks=[]
    for r in range(h-2):
        for c in range(w-2):
            v=g[r][c]
            if v and all(g[r+i][c+j]==v for i in range(3) for j in range(3)):
                blocks.append((r+1,c+1,v))
    for (mr,mc,v) in blocks:
        for c in range(w): out[mr][c]=v
        for r in range(h): out[r][mc]=v
    for i in range(len(blocks)):
        for j in range(i+1,len(blocks)):
            out[blocks[i][0]][blocks[j][1]]=0
            out[blocks[j][0]][blocks[i][1]]=0
    return out

o=transform(G['Demo pair 1 input'])
print(o==G['Demo pair 1 output'])
import numpy as np
if o!=G['Demo pair 1 output']:
    print(np.array(o)-np.array(G['Demo pair 1 output']))
print(json.dumps(transform(G['Test input'])))
